import { registerNodeKind, baseNode, pin, runWorkerJob } from "@merlin/plugin-api";

for (const op of ["bang", "login", "status"]) {
  const kind = "rodinCanvas." + op;
  const isMesh = op === "bang";
  const label = { bang: "Rodin BANG", login: "Rodin Sign In", status: "Rodin Account Status" }[op];
  const description = {
    bang: "Split a model generated by this Rodin extension into parts.",
    login: "Sign in to Hyper3D in your browser with a device code.",
    status: "Check whether this extension has a saved Rodin session."
  }[op];
  registerNodeKind({
    kind,
    meta: { label, color: "#287c7c", category: isMesh ? "Geometry" : "Custom", description },
    factory: (pos = {x: 0, y: 0}) => baseNode(kind, label, pos, isMesh
      ? [pin("source", "mesh", "input"), pin("mesh", "mesh", "output")]
      : [pin("text", "text", "output")], isMesh ? {strength: 5} : {}),
    traits: { isGeneration: true },
    adapter: {
      handles: [kind],
      async run({ node, inputs, signal, onProgress, canvasId, requireReviewedModels, live }) {
        if (live) throw new Error("Run this Rodin card once, outside the live loop.");
        if (isMesh && !inputs.source) throw new Error("Connect a mesh generated by this Rodin extension.");
        const result = await runWorkerJob("rodin-canvas-" + op,
          { inputs: isMesh ? {mesh: inputs.source} : {}, params: node.params },
          { signal, onProgress, canvasId, nodeId: node.id, requireReviewedModels });
        return isMesh ? { outputFilePaths: {"output.glb": result.mesh} } : { outputValues: {text: result.text} };
      }
    }
  });
}


registerNodeKind({
  kind: "rodinCanvas.textMesh",
  meta: {label: "Rodin Text to Mesh", color: "#287c7c", category: "Generate",
    description: "Generate a Rodin GLB from a connected text prompt."},
  factory: (pos = {x: 0, y: 0}) => baseNode("rodinCanvas.textMesh", "Rodin Text to Mesh", pos,
    [pin("prompt", "text", "input"), pin("mesh", "mesh", "output")]),
  traits: {isGeneration: true},
  adapter: {
    handles: ["rodinCanvas.textMesh"],
    async run({node, inputs, signal, onProgress, canvasId, requireReviewedModels, live}) {
      if (live) throw new Error("Run this Rodin card outside the live loop.");
      if (!String(inputs.prompt ?? "").trim()) throw new Error("Connect a text prompt.");
      const result = await runWorkerJob("rodin-canvas-text-card", {inputs: {prompt: inputs.prompt}},
        {signal, onProgress, canvasId, nodeId: node.id, requireReviewedModels});
      return {outputFilePaths: {"output.glb": result.mesh}};
    }
  }
});
